function findNextDockColumn(group, startColIdx) {
  const n = columns.length;
  // Search in conveyor order: (startColIdx + 1), (startColIdx + 2), ...
  // Prefer same-color match or empty column on other columns
  for (let step = 1; step < n; step++) {
    const idx = (startColIdx + step) % n;
    if (canDock(group, idx)) {
      return idx;
    }
  }
  return -1;
}
